export default async function list({ bucket, region, prefix }, context) {
  if (!bucket || bucket.startsWith("YOUR_") || !region) throw Error("Configure bucket and region");
  const objects = [],
    seen = new Set();
  let token = null;
  do {
    const page = await context.actions.call("aws_s3.list_objects", {
      bucket,
      region,
      prefix,
      delimiter: "/",
      maxKeys: 1000,
      ...(token ? { continuationToken: token } : {}),
    });
    if (!Array.isArray(page.objects) || typeof page.isTruncated !== "boolean")
      throw Error("Invalid S3 page");
    for (const o of page.objects) {
      if (typeof o.name !== "string" || !o.name.startsWith(prefix) || !Number.isSafeInteger(o.size))
        throw Error("Invalid S3 object");
      if (o.size > 0 && !o.name.endsWith("/")) objects.push(o);
    }
    const next = page.isTruncated ? page.nextContinuationToken : null;
    if (page.isTruncated && (!next || seen.has(next))) throw Error("Invalid continuation token");
    if (next) seen.add(next);
    token = next;
  } while (token);
  return { objects };
}

